    // 2. Build environment for the runner wrapper (and inherited by executor).
    const childEnv: NodeJS.ProcessEnv = {
      ...process.env,
      ...this.extraEnv,
      // Formal ABI env vars — passed through to the executor
      TASK_ID: taskId,
      FEATURE_ID: featureId,
      WORKSPACE_ID: workspaceId,
      TASK_REPO_URL: taskRepoUrl,
      TASK_REPO_BRANCH: taskRepoBranch,
      TASK_BASE_BRANCH: taskBaseBranch,
      TASK_REPO_BASE_BRANCH: taskRepoBaseBranch,
      EXECUTOR_WORKDIR: executorWorkdir,
      MGMT_REPO_URL: mgmtRepoUrl,
      BRIEFING_PATH: briefingPath,
      RESULT_PATH: resultPath,
      GITHUB_TOKEN: githubToken,
      ...(sshPrivateKey ? { SSH_PRIVATE_KEY: sshPrivateKey } : {}),
      ...(budgetTokens !== undefined ? { BUDGET_TOKENS: String(budgetTokens) } : {}),
      ...(implementationModel ? { IMPLEMENTATION_MODEL: implementationModel } : {}),
      // Runner wrapper contract (T-Q10)
      CALLBACK_URL: callbackUrl,
      HANDLE: handle,
      NONCE: nonce,
      ...(this.executorBinPath ? { EXECUTOR_BIN: this.executorBinPath } : {}),
    };

    emit({
      type: "executor_spawn",
      task_id: taskId,
      feature_id: featureId,
      handle,
      runner: this.runnerBinPath,
    });

    // 3. Spawn runner wrapper — non-blocking; returns immediately.
    const child = spawn("node", [this.runnerBinPath], {
      env: childEnv,
      stdio: "inherit",
      detached: false,
    });

    // 4. Track in supervision map.
    this.supervision.set(handle, {
      pid: child.pid ?? 0,
      startedAt,
      nonce,
      callbackUrl,
      resultPath,
      taskId,
      featureId,
    });

    // 5. Watchdog: kill runner if it exceeds the wall-clock timeout.
    let watchdog: ReturnType<typeof setTimeout> | null = setTimeout(() => {
      watchdog = null;
      if (!child.killed) {
        emit({
          type: "executor_timeout",
          task_id: taskId,
          feature_id: featureId,
          handle,
          timeout_ms: this.timeoutMs,
        });
        child.kill("SIGTERM");
      }
    }, this.timeoutMs);
    // Don't hold the event loop open for the watchdog.
    if (watchdog.unref) watchdog.unref();

    // 6. Safety net: if the runner exits without the broker receiving a
    //    callback within crashGraceMs, synthesize a "failed" completion.
    child.on("exit", (code, signal) => {
      if (watchdog !== null) {
        clearTimeout(watchdog);
        watchdog = null;
      }

      emit({
        type: "executor_exit",
        task_id: taskId,
        feature_id: featureId,
        handle,
        exit_code: code,
        signal,
      });

      // Exit code 0 means runner.js completed its postWithRetry successfully —
      // the broker already has the real result. Skip the safety net entirely.
      // The supervision entry stays so ack() can still clean up the result file.
      if (code === 0 && signal === null) {
        return;
      }

      const graceTimer: ReturnType<typeof setTimeout> = setTimeout(() => {
        if (!this.supervision.has(handle)) return; // already acked
        const entry = this.supervision.get(handle)!;
        this.supervision.delete(handle);

        if (!entry.callbackUrl) return; // no callback URL to POST to

        const reason = signal
          ? `runner_killed_by_signal: ${signal}`
          : code !== null && code !== 0
            ? `runner_crashed (exit ${code})`
            : "runner_no_callback";

        emit({
          type: "executor_safety_net",
          task_id: entry.taskId,
          feature_id: entry.featureId,
          handle,
          reason,
        });

        const body = JSON.stringify({
          handle,
          nonce: entry.nonce,
          result: { terminal_status: "failed", blocked_reason: reason },
        });

        _httpPost(entry.callbackUrl, body).catch(() => {
          // Best-effort — ignore POST failures in the safety net.
        });
      }, this.crashGraceMs);

      // Don't hold the event loop open for the grace timer.
      if (graceTimer.unref) graceTimer.unref();
    });

    return handle;
  }

  /**
   * Wave 3: result arrives via broker callback — readResult is a no-op for
   * this profile. Returns a "failed / handle_not_found" tombstone so callers
   * that mistakenly poll readResult get a predictable signal.
   */
  async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
    return { terminal_status: "failed", blocked_reason: "handle_not_found" };
  }

  // ── Supervision helpers ───────────────────────────────────────────────────

  /**
   * Acknowledge a completed handle:
   *  - Removes the entry from the supervision map (disarms the safety net).
   *  - Deletes the temp result file written by the executor.
   *  - Delegates to broker.ack to commit consumption in the broker.
   *
   * Call this after the orchestrator has successfully processed the completion
   * returned by broker.listCompleted.
   */
  async ack(handle: ExecutorHandle): Promise<void> {
    const entry = this.supervision.get(handle);
    if (entry) {
      this.supervision.delete(handle);
      try {
        unlinkSync(entry.resultPath);
      } catch {
        // Best-effort — file may already be gone.
      }
      if (this.workspacesDir) {
        try {
          rmSync(join(this.workspacesDir, `exec-${handle}`), { recursive: true, force: true });
        } catch {
          // Best-effort — dir may not exist (e.g. executor never wrote to it).
        }
      }
    }
    if (this.broker) {
      await this.broker.ack(handle);
    }
  }

  /** Number of handles currently tracked in the supervision map. */
  supervisionSize(): number {
    return this.supervision.size;
  }
}

/**
 * DockerRunAdapter — ExecutorPort adapter for the local-docker profile (T8).
 *
 * submit() registers the handle with the broker, then runs:
 *   docker run -d \
 *     --name exec-<handle> \
 *     --network agents-net \
 *     --entrypoint /platform/runner.js \
 *     --restart=no \
 *     -v /platform-bin:/platform:ro \
 *     -v /workspaces/<task>:/workspace:rw \
 *     -e BRIEFING_PATH ... -e CALLBACK_URL ... \
 *     --label platform.handle=<handle> \
 *     executor:current
 *
 * The container runs the runner wrapper as PID 1. When the wrapper exits
 * (after POSTing result to broker), the container exits naturally.
 * `--rm` is NOT used so docker logs / inspect remain available until ack().
 *
 * Wrapper-crash safety net:
 *   `docker wait <container_id>` is run in background. If the container
 *   exits without a corresponding broker callback arriving within crashGraceMs,
 *   the adapter synthesises a "failed" completion via the broker's callback URL.
 *
 * ack():
 *   Runs `docker rm <container_id>` to clean up the exited container, and
 *   unlinks the result file. Delegates to broker.ack() to commit consumption.
 *
 * Orphan sweep:
 *   A periodic sweep scans `docker ps -a -f label=platform.handle=<handle>`
 *   for exited containers whose handles are no longer in the supervision map
 *   (i.e. have already been acked or are unknown) and removes them.
 */

import { unlinkSync, rmSync } from "node:fs";
import { join } from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import * as http from "node:http";
import * as https from "node:https";
import type {
  ExecutorPort,
  ExecutorPortInput,
  ExecutorHandle,
  ExecutorResult,
  CompletionBrokerPort,
} from "@workflow/runtime-abi";

const execFileAsync = promisify(execFile);

// ── Types ─────────────────────────────────────────────────────────────────────

export interface DockerRunAdapterOpts {
  /**
   * Docker image to run as the executor.
   * Defaults to the standard executor image tag.
   */
  executorImage?: string;

  /**
   * Path to the runner.js wrapper inside the container.
   * Defaults to /platform/runner.js (mounted via platformBinDir).
   */
  runnerEntrypoint?: string;

  /**
   * Host path to the directory containing runner.js.
   * Mounted read-only into the container at /platform.
   * Defaults to /workflow/runtime/runner-wrapper (standard container path).
   */
  platformBinDir?: string;

  /**
   * Host directory under which per-handle workspace dirs live.
   * Each executor gets an isolated subdirectory at `<workspacesDir>/exec-<handle>`.
   * Mounted read-write into the container at /workspace.
   * If not set, workspace mounting is skipped (tests may skip this).
   */
  workspacesDir?: string;

  /**
   * Docker bridge network the containers join so they can reach the broker
   * by service-name DNS (e.g. `broker:7000`).
   * Defaults to `agents-net`.
   */
  dockerNetwork?: string;

  /**
   * Maximum wall-clock milliseconds before the watchdog kills the container.
   * Defaults to 2 hours.
   */
  timeoutMs?: number;

  /**
   * Grace window (ms) after container exit before the safety-net synthetic
   * failure is posted to the broker. Allows a callback that was in-flight at
   * crash time to arrive before we synthesize a failure.
   * Default: 5 000 ms.
   */
  crashGraceMs?: number;

  /**
   * How often the orphan sweep runs (ms). Pass 0 to disable.
   * Default: 60 000 ms.
   */
  orphanSweepIntervalMs?: number;

  /**
   * CompletionBrokerPort instance. Required for the async callback flow.
   * If absent, broker.register is skipped (useful in isolated unit tests).
   */
  broker?: CompletionBrokerPort;

  /**
   * Extra environment variables passed to the container.
   */
  extraEnv?: Record<string, string>;

  /**
   * Override the docker binary path (useful in tests).
   * Default: "docker".
   */
  dockerBin?: string;
}

interface SupervisionEntry {
  containerId: string;
  containerName: string;
  startedAt: string; // ISO 8601
  nonce: string;
  callbackUrl: string;
  resultPath: string;
  taskId: string;
  featureId: string;
}

// ── Defaults ──────────────────────────────────────────────────────────────────

const DEFAULT_EXECUTOR_IMAGE = "executor:current";
const DEFAULT_RUNNER_ENTRYPOINT = "/platform/runner.js";
const DEFAULT_PLATFORM_BIN_DIR = "/workflow/runtime/runner-wrapper";
const DEFAULT_DOCKER_NETWORK = "agents-net";
const DEFAULT_TIMEOUT_MS = 7_200_000;
const DEFAULT_CRASH_GRACE_MS = 5_000;
const DEFAULT_ORPHAN_SWEEP_MS = 60_000;

// ── Helpers ───────────────────────────────────────────────────────────────────

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

/** HTTP POST — resolves regardless of response status. Rejects on transport error. */
function _httpPost(url: string, body: string): Promise<void> {
  return new Promise((resolve, reject) => {
    let u: URL;
    try {
      u = new URL(url);
    } catch {
      reject(new Error(`_httpPost: invalid URL: ${url}`));
      return;
    }
    const lib: typeof http | typeof https = u.protocol === "https:" ? https : http;
    const req = lib.request(
      {
        hostname: u.hostname,
        port: u.port || (u.protocol === "https:" ? 443 : 80),
        path: u.pathname + u.search,
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
        },
      },
      (res) => {
        res.resume();
        resolve();
      },
    );
    req.on("error", reject);
    req.write(body);
    req.end();
  });
}

// ── DockerRunAdapter ──────────────────────────────────────────────────────────

export class DockerRunAdapter implements ExecutorPort {
  private readonly executorImage: string;
  private readonly runnerEntrypoint: string;
  private readonly platformBinDir: string;
  private readonly workspacesDir: string | undefined;
  private readonly dockerNetwork: string;
  private readonly timeoutMs: number;
  private readonly crashGraceMs: number;
  private readonly orphanSweepIntervalMs: number;
  private readonly broker: CompletionBrokerPort | null;
  private readonly extraEnv: Record<string, string>;
  private readonly dockerBin: string;

  /** Keyed by handle; tracks in-flight containers for the safety-net sweep. */
  private readonly supervision = new Map<ExecutorHandle, SupervisionEntry>();

  private orphanSweepTimer: ReturnType<typeof setInterval> | null = null;

  constructor(opts: DockerRunAdapterOpts = {}) {
    this.executorImage = opts.executorImage ?? DEFAULT_EXECUTOR_IMAGE;
    this.runnerEntrypoint = opts.runnerEntrypoint ?? DEFAULT_RUNNER_ENTRYPOINT;
    this.platformBinDir = opts.platformBinDir ?? DEFAULT_PLATFORM_BIN_DIR;
    this.workspacesDir = opts.workspacesDir;
    this.dockerNetwork = opts.dockerNetwork ?? DEFAULT_DOCKER_NETWORK;
    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
    this.crashGraceMs = opts.crashGraceMs ?? DEFAULT_CRASH_GRACE_MS;
    this.orphanSweepIntervalMs = opts.orphanSweepIntervalMs ?? DEFAULT_ORPHAN_SWEEP_MS;
    this.broker = opts.broker ?? null;
    this.extraEnv = opts.extraEnv ?? {};
    this.dockerBin = opts.dockerBin ?? "docker";

    if (this.orphanSweepIntervalMs > 0) {
      this.orphanSweepTimer = setInterval(() => {
        this._orphanSweep().catch((err) => {
          emit({ type: "orphan_sweep_error", error: String(err) });
        });
      }, this.orphanSweepIntervalMs);
      if (this.orphanSweepTimer.unref) this.orphanSweepTimer.unref();
    }
  }

  // ── ExecutorPort ──────────────────────────────────────────────────────────

  async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
    const {
      taskId,
      featureId,
      workspaceId,
      handle,
      taskRepoUrl,
      taskRepoBranch,
      taskBaseBranch,
      taskRepoBaseBranch,
      executorWorkdir,
      mgmtRepoUrl,
      briefingPath,
      resultPath,
      budgetTokens,
      implementationModel,
      sshPrivateKey,
      githubToken,
      callbackUrl,
      nonce,
    } = input;
    const startedAt = new Date().toISOString();
    const containerName = `exec-${handle}`;

    // 1. Register handle with broker before spawning so callback arriving
    //    before submit returns is still accepted.
    if (this.broker) {
      await this.broker.register(handle, nonce, {
        kind: input.kind ?? "impl",
        task_id: taskId,
        feature_id: featureId,
        started_at: startedAt,
      });
    }

    // 2. Build docker run arguments.
    const envArgs: string[] = [
      "-e", `TASK_ID=${taskId}`,
      "-e", `FEATURE_ID=${featureId}`,
      "-e", `WORKSPACE_ID=${workspaceId}`,
      "-e", `TASK_REPO_URL=${taskRepoUrl}`,
      "-e", `TASK_REPO_BRANCH=${taskRepoBranch}`,
      "-e", `TASK_BASE_BRANCH=${taskBaseBranch}`,
      ...(taskRepoBaseBranch !== undefined ? ["-e", `TASK_REPO_BASE_BRANCH=${taskRepoBaseBranch}`] : []),
      "-e", `EXECUTOR_WORKDIR=${executorWorkdir}`,
      "-e", `MGMT_REPO_URL=${mgmtRepoUrl}`,
      "-e", `BRIEFING_PATH=${briefingPath}`,
      "-e", `RESULT_PATH=${resultPath}`,
      "-e", `GITHUB_TOKEN=${githubToken}`,
      "-e", `CALLBACK_URL=${callbackUrl}`,
      "-e", `HANDLE=${handle}`,
      "-e", `NONCE=${nonce}`,
    ];

    if (sshPrivateKey) {
      envArgs.push("-e", `SSH_PRIVATE_KEY=${sshPrivateKey}`);
    }
    if (budgetTokens !== undefined) {
      envArgs.push("-e", `BUDGET_TOKENS=${budgetTokens}`);
    }
    if (implementationModel) {
      envArgs.push("-e", `IMPLEMENTATION_MODEL=${implementationModel}`);
    }

    for (const [k, v] of Object.entries(this.extraEnv)) {
      envArgs.push("-e", `${k}=${v}`);
    }

    const volumeArgs: string[] = [
      "-v", `${this.platformBinDir}:/platform:ro`,
    ];
    if (this.workspacesDir) {
      volumeArgs.push("-v", `${this.workspacesDir}/exec-${handle}:/workspace:rw`);
    }

    const dockerArgs = [
      "run", "-d",
      "--name", containerName,
      "--network", this.dockerNetwork,
      "--entrypoint", this.runnerEntrypoint,
      "--restart=no",
      "--label", `platform.handle=${handle}`,
      ...envArgs,
      ...volumeArgs,
      this.executorImage,
    ];

    emit({
      type: "executor_spawn",
      task_id: taskId,
      feature_id: featureId,
      handle,
      container_name: containerName,
      image: this.executorImage,
    });

    // 3. docker run -d — returns container ID immediately.
    let containerId: string;
    try {
      const { stdout } = await execFileAsync(this.dockerBin, dockerArgs);
      containerId = stdout.trim();
    } catch (err) {
      // If docker run fails, unregister the handle and rethrow.
      if (this.broker) {
        await this.broker.ack(handle).catch(() => {/* best-effort */});
      }
      throw err;
    }

    // 4. Track in supervision map.
    this.supervision.set(handle, {
      containerId,
      containerName,
      startedAt,
      nonce,
      callbackUrl,
      resultPath,
      taskId,
      featureId,
    });

    // 5. docker wait as the wrapper-crash safety net (runs async).
    this._watchContainer(handle, containerId, containerName, callbackUrl, nonce, taskId, featureId);

    return handle;
  }

  /**
   * readResult is a no-op for local-docker — result rides in the callback.
   * Returns a tombstone so callers that mistakenly call readResult get a
   * predictable signal.
   */
  async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
    return { terminal_status: "failed", blocked_reason: "handle_not_found" };
  }

  // ── ack ───────────────────────────────────────────────────────────────────

  /**
   * Acknowledge a completed handle:
   *  - Removes the entry from the supervision map (disarms the safety net).
   *  - Runs `docker rm <container_id>` to clean up the exited container.
   *  - Unlinks the result file.
   *  - Delegates to broker.ack.
   */
  async ack(handle: ExecutorHandle): Promise<void> {
    const entry = this.supervision.get(handle);
    if (entry) {
      this.supervision.delete(handle);

      // docker rm — best-effort; container may already be removed.
      try {
        await execFileAsync(this.dockerBin, ["rm", entry.containerId]);
      } catch {
        // Container may already be gone (manual cleanup, restart, etc.).
      }

      // Unlink result file — best-effort.
      try {
        unlinkSync(entry.resultPath);
      } catch {
        // File may already be gone.
      }

      // Remove per-handle workdir on the host — best-effort.
      if (this.workspacesDir) {
        try {
          rmSync(join(this.workspacesDir, `exec-${handle}`), { recursive: true, force: true });
        } catch {
          // Dir may not exist (e.g. executor never wrote to it).
        }
      }
    }

    if (this.broker) {
      await this.broker.ack(handle);
    }
  }

  // ── Supervision helpers ───────────────────────────────────────────────────

  /** Number of handles currently tracked in the supervision map. */
  supervisionSize(): number {
    return this.supervision.size;
  }

  /** Stop the orphan sweep timer. Call during graceful shutdown. */
  stopOrphanSweep(): void {
    if (this.orphanSweepTimer) {
      clearInterval(this.orphanSweepTimer);
      this.orphanSweepTimer = null;
    }
  }

  // ── Internal ─────────────────────────────────────────────────────────────

  /**
   * Run `docker wait <containerId>` in the background. When the container
   * exits, if the handle is still in the supervision map (no callback arrived
   * yet), fire a synthetic "failed" completion to the broker after crashGraceMs.
   */
  private _watchContainer(
    handle: ExecutorHandle,
    containerId: string,
    containerName: string,
    callbackUrl: string,
    nonce: string,
    taskId: string,
    featureId: string,
  ): void {
    // Watchdog: kill the container if it exceeds the wall-clock timeout.
    let watchdog: ReturnType<typeof setTimeout> | null = setTimeout(() => {
      watchdog = null;
      emit({
        type: "executor_timeout",
        task_id: taskId,
        feature_id: featureId,
        handle,
        container_id: containerId,
        timeout_ms: this.timeoutMs,
      });
      execFileAsync(this.dockerBin, ["stop", containerName]).catch(() => {/* best-effort */});
    }, this.timeoutMs);
    if (watchdog.unref) watchdog.unref();

    // docker wait — blocks until container exits; run async.
    execFileAsync(this.dockerBin, ["wait", containerId])
      .then(({ stdout }) => {
        const exitCode = parseInt(stdout.trim(), 10);

        if (watchdog !== null) {
          clearTimeout(watchdog);
          watchdog = null;
        }

        emit({
          type: "executor_exit",
          task_id: taskId,
          feature_id: featureId,
          handle,
          container_id: containerId,
          exit_code: exitCode,
        });

        // Grace timer before firing safety net.
        const graceTimer = setTimeout(() => {
          if (!this.supervision.has(handle)) return; // already acked
          const entry = this.supervision.get(handle)!;
          this.supervision.delete(handle);

          const reason =
            exitCode !== 0
              ? `runner_crashed (exit ${exitCode})`
              : "runner_no_callback";

          emit({
            type: "executor_safety_net",
            task_id: entry.taskId,
            feature_id: entry.featureId,
            handle,
            container_id: containerId,
            reason,
          });

          const body = JSON.stringify({
            handle,
            nonce: entry.nonce,
            result: { terminal_status: "failed", blocked_reason: reason },
          });

          _httpPost(entry.callbackUrl, body).catch(() => {
            // Best-effort — ignore POST failures in the safety net.
          });
        }, this.crashGraceMs);

        if (graceTimer.unref) graceTimer.unref();
      })
      .catch(() => {
        // docker wait failed (container removed before we could wait, etc.).
        // The safety net won't fire, but the broker's visibility timeout will
        // reclaim the completion eventually.
        if (watchdog !== null) {
          clearTimeout(watchdog);
          watchdog = null;
        }
      });
  }

  /**
   * Periodic orphan sweep.
   *
   * Lists all containers with a `platform.handle` label, checks which ones
   * are exited and whose handles are NOT in the in-flight supervision map
   * (i.e. already acked or never registered), and removes them.
   */
  private async _orphanSweep(): Promise<void> {
    let stdout: string;
    try {
      const result = await execFileAsync(this.dockerBin, [
        "ps", "-a",
        "--filter", "label=platform.handle",
        "--format", "{{.ID}}\t{{.Label \"platform.handle\"}}\t{{.Status}}",
      ]);
      stdout = result.stdout;
    } catch {
      return; // docker unavailable; skip sweep
    }

    const lines = stdout.trim().split("\n").filter(Boolean);
    for (const line of lines) {
      const [containerId, handle, status] = line.split("\t");
      if (!containerId || !handle || !status) continue;

      // Only remove exited containers whose handles are not in supervision.
      if (status.toLowerCase().startsWith("exited") && !this.supervision.has(handle)) {
        emit({
          type: "orphan_container_removed",
          container_id: containerId,
          handle,
        });
        execFileAsync(this.dockerBin, ["rm", containerId]).catch(() => {/* best-effort */});
      }
    }
  }
}

